class Notifikasi {
  constructor(pesan) {
    this.pesan = pesan;
  }
  kirim() {
    return `[Umum] ${this.pesan}`;
  }
}
class Email extends Notifikasi {
  kirim() {
    return `[Email] ${this.pesan}`;
  }
}
class SMS extends Notifikasi {
  kirim() {
    return `[SMS] ${this.pesan.slice(0, 10)}`;
  }
}
const semua = [new Email("Tagihan bulan ini"), new SMS("Kode OTP 482913"), new Notifikasi("Halo")];
for (const n of semua) {
  console.log(n.kirim());
}

