class Karyawan {
  constructor(nama, gaji) {
    this.nama = nama;
    this.gaji = gaji;
  }
  hitungGaji() {
    return this.gaji;
  }
}
class Freelancer extends Karyawan {
  constructor(nama, jam, tarif) {
    super(nama, 0);
    this.jam = jam;
    this.tarif = tarif;
  }
  hitungGaji() {
    return this.jam * this.tarif;
  }
}
const tim = [
  new Karyawan("Rina", 8000000),
  new Freelancer("Budi", 40, 100000),
  new Karyawan("Sari", 7000000),
];
let total = 0;
for (const orang of tim) {
  console.log(`${orang.nama}: ${orang.hitungGaji()}`);
  total += orang.hitungGaji();
}
console.log(`Total: ${total}`);
